import sys, os, dis, importlib.util
from collections import defaultdict

repo = '/testbed'
test_file = '/testbed/qa_instances_eval/python-control/bdalg_combine_tf_def_use_intersection_suite/files/tests/qa/bdalg_combine_tf_def_use_intersection_suite_test.py'
if repo not in sys.path:
    sys.path.insert(0, repo)

spec = importlib.util.spec_from_file_location('qa_test_mod', test_file)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

tracked = {
    'col', 'den', 'den_row', 'dt', 'dt_list', 'dt_set', 'ensured_row',
    'ensured_tf_array', 'j_in', 'j_out', 'num', 'num_row', 'row',
    'row_index', 'tf_array', 'tfn'
}

import control.bdalg as bdalg
combine_tf = bdalg.combine_tf
co = combine_tf.__code__
firstlineno = co.co_firstlineno

instr_map = {i.offset: i for i in dis.get_instructions(combine_tf)}

results = {}

def run_case(method_name):
    pairs = set()
    last_def = {}

    def tracer(frame, event, arg):
        nonlocal pairs, last_def
        if event == 'call':
            if frame.f_code is co:
                frame.f_trace_opcodes = True
                # parameters defined on function definition line
                for name in tracked:
                    if name in frame.f_locals:
                        last_def[name] = firstlineno
                return tracer
            return tracer
        if frame.f_code is not co:
            return tracer
        if event == 'opcode':
            instr = instr_map.get(frame.f_lasti)
            if instr is None:
                return tracer
            op = instr.opname
            if op in ('LOAD_FAST', 'STORE_FAST'):
                name = instr.argval
                if name in tracked:
                    line = frame.f_lineno
                    if op == 'LOAD_FAST':
                        if name in last_def:
                            pairs.add((name, last_def[name], line))
                    else:
                        last_def[name] = line
        return tracer

    old = sys.gettrace()
    sys.settrace(tracer)
    try:
        inst = mod.TestCombineTfDefUseIntersectionQA()
        getattr(inst, method_name)()
    finally:
        sys.settrace(old)

    results[method_name] = pairs

methods = [f'test_case_{i:02d}' for i in range(1, 11)]
for m in methods:
    run_case(m)

intersection = set.intersection(*(results[m] for m in methods))

print('INTERSECTION_COUNT', len(intersection))
for item in sorted(intersection, key=lambda x: (x[0], x[1], x[2])):
    print(item)

# print per-test counts for sanity
for m in methods:
    print(m, len(results[m]))
